            color = grid[r][c]
            if color not in (1, 2, 3, 6):
                continue
            if color == 1:
                steps = [(0, 1), (0, 1), (-1, 0)]
            elif color == 2:
                steps = [(0, -1)] * 4
            elif color == 3:
                steps = [(1, 0)] * 3
            else:
                steps = [(-1, 0)] * 6
            cells = [(r, c)]
            rr, cc = r, c
            for dr, dc in steps:
                rr, cc = rr + dr, cc + dc
                if 0 <= rr < h and 0 <= cc < w:
                    cells.append((rr, cc))
                else:
                    break
            for q, (ar, ac) in enumerate(cells[1:], 1):
                out[ar][ac] = color if q == len(cells) - 1 else 5
            paths.append((color, cells))
    collisions = set()
    for i, (color_a, cells_a) in enumerate(paths):
        for color_b, cells_b in paths[i + 1:]:
            if color_a == color_b:
                continue
            for pos in set(cells_a[1:]) & set(cells_b[1:]):
                collisions.add(pos)
    for r, c in collisions:
        rr, cc = r, c
        while 0 <= rr < h and 0 <= cc < w:
            out[rr][cc] = 4
            rr += 1
            cc -= 1
    return out
